/* DAA Exam Practice — single-page app, no build step.
 * Data: window.BANK (data/bank.js, generated by build/build.py).
 * SQL questions run in the browser with sql.js against the same .db files
 * students can download; Excel answers are compared to values computed from the files. */
(() => {
  "use strict";
  const B = window.BANK;
  const Q = Object.fromEntries(B.questions.map(q => [q.id, q]));
  const EX = Object.fromEntries(B.exams.map(e => [e.id, e]));
  const REG = Object.fromEntries(B.regression.map(r => [r.id, r]));
  const DS = B.datasets;
  const app = document.getElementById("app");
  const SQLJS_CDN = "https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/";

  // ------------------------------------------------------------------ helpers
  const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const $ = (sel, root = document) => root.querySelector(sel);
  const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
  const fmtNum = (v, d = 2) => Number(v).toLocaleString("en-US", { maximumFractionDigits: d });
  const fmtSize = b => b > 1e6 ? (b / 1e6).toFixed(1) + " MB" : Math.max(1, Math.round(b / 1e3)) + " kB";
  const clock = s => { const a = Math.abs(Math.round(s)); return (s < 0 ? "−" : "") + Math.floor(a / 60) + ":" + String(a % 60).padStart(2, "0"); };
  const subjChip = s => `<span class="chip ${s === "SQL" ? "sql" : "excel"}">${esc(s)}</span>`;
  const topicLabel = t => t.replace(/_/g, " ");

  // ------------------------------------------------------------------ progress (this browser only)
  const KEY = "daa-practice-v1";
  const Store = {
    data: { q: {}, exams: {}, reg: {}, concepts: {} },
    load() { try { const raw = localStorage.getItem(KEY); if (raw) Object.assign(this.data, JSON.parse(raw)); } catch (e) { /* storage unavailable */ } },
    save() { try { localStorage.setItem(KEY, JSON.stringify(this.data)); } catch (e) { /* ignore */ } },
    q(id) { return this.data.q[id] || null; },
    recordQ(id, ok) {
      const r = this.data.q[id] || { attempts: 0, fails: 0, solved: false };
      r.attempts++;
      if (!ok) r.fails = (r.fails || 0) + 1;
      if (ok && !r.solved) { r.solved = true; r.firstTry = r.attempts === 1; }
      r.at = Date.now();
      this.data.q[id] = r; this.save();
    },
    status(id) { const r = this.q(id); return !r ? "" : r.solved ? "ok" : "bad"; },
  };
  Store.load();

  // ------------------------------------------------------------------ answer checking
  // Answers are stored only as fingerprints (see build/fingerprint.py): the page can
  // confirm an answer and recognise known mistakes without containing the answer.
  // normCell, roundTo, the separators and the sort order must match the build.
  const SALT = "daa-practice/", ITERATIONS = 20000, CELL = "\x1f", ROW = "\x1e";
  const enc = new TextEncoder();
  async function fp(qid, text) {
    const key = await crypto.subtle.importKey("raw", enc.encode(text), "PBKDF2", false, ["deriveBits"]);
    const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: enc.encode(SALT + qid), iterations: ITERATIONS }, key, 256);
    return [...new Uint8Array(bits)].map(b => b.toString(16).padStart(2, "0")).join("").slice(0, 32);
  }
  function roundTo(x, d) {
    const p = Math.pow(10, d);
    const s = (Math.floor(x * p + 0.5) / p).toFixed(d);
    return s.startsWith("-") && Number(s) === 0 ? s.slice(1) : s;
  }
  const NUMERIC = /^[-+]?\d+(\.\d+)?([eE][-+]?\d+)?$/;
  function normCell(v) {
    if (v === null || v === undefined) return "∅";
    if (typeof v === "number") return "#" + roundTo(v, 2);
    const s = String(v).trim();
    return NUMERIC.test(s) ? "#" + roundTo(Number(s), 2) : s.toLowerCase();
  }
  const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);   // UTF-16 code unit order, as in the build
  const normText = s => String(s).toLowerCase().split(/\s+/).filter(Boolean).join(" ").replace(/^["']+|["']+$/g, "");

  function parseNumber(raw) {
    const cleaned = raw.replace(/[\s$%,]/g, "").replace(/^\((.*)\)$/, "-$1").replace(/[−–]/g, "-");
    const v = Number(cleaned);
    return cleaned && Number.isFinite(v) ? v : null;
  }

  // Typed (Excel) answers. Returns {ok, msg, hint}.
  async function checkTyped(q, input) {
    const c = q.check, raw = String(input || "").trim();
    if (!raw) return { empty: true, msg: "Enter an answer first." };
    let h;
    if (c.type === "number") {
      const v = parseNumber(raw);
      if (v === null) return { ok: false, msg: "That is not a number. Use digits only, e.g. 1234.56." };
      h = await fp(q.id, "num" + roundTo(v, c.decimals));
      if (c.accept.includes(h)) return { ok: true, msg: "Correct." };
      const m = c.mistakes.find(x => x.fp === h);
      if (m) return { ok: false, msg: "Not correct yet.", hint: m.hint };
      if (c.near && (await fp(q.id, "near" + roundTo(v, c.decimals - 1))) === c.near)
        return { ok: false, msg: "Very close — check your rounding.", hint: `Give the answer with ${c.decimals} decimal${c.decimals > 1 ? "s" : ""}.` };
      return { ok: false, msg: "Not correct yet. This is not one of the common mistakes either — retrace your steps." };
    }
    h = await fp(q.id, "txt" + normText(raw));
    if (c.accept.includes(h)) return { ok: true, msg: "Correct." };
    const m = c.mistakes.find(x => x.fp === h);
    if (m) return { ok: false, msg: "Not correct yet.", hint: m.hint };
    return { ok: false, msg: "Not correct yet. Check the spelling and use the exact value from the data." };
  }

  // SQL results are reconciled like control totals: columns, rows, the values in each
  // column, how they combine into rows and (if asked) the order. Column names and the
  // order of the columns do not matter; numbers are compared at 2 decimals.
  async function reconcile(q, res) {
    const c = q.check;
    const cols = res ? res.columns.length : 0;
    const rows = res ? res.values : [];
    const items = [];
    const out = { ok: false, items, hint: null };
    if (!cols) { items.push({ ok: false, label: "Result", note: "your statement returned no table" }); return out; }
    const norm = rows.map(r => r.map(normCell));
    const colH = await Promise.all(res.columns.map((_, j) => fp(q.id, "col" + norm.map(r => r[j]).sort(cmp).join(CELL))));
    const order = [...colH.keys()].sort((a, b) => cmp(colH[a], colH[b]));
    const canon = norm.map(r => order.map(j => r[j]).join(CELL));
    const setH = await fp(q.id, "set" + [...canon].sort(cmp).join(ROW));
    const mistake = c.mistakes.find(m => m.fp === setH);
    if (mistake) out.hint = mistake.hint;

    items.push(cols === c.cols ? { ok: true, label: "Columns", note: `${cols} as asked` }
      : { ok: false, label: "Columns", note: cols > c.cols ? "more columns than the question asks for" : "fewer columns than the question asks for" });
    items.push(rows.length === c.rows ? { ok: true, label: "Rows", note: "row count reconciles" }
      : { ok: false, label: "Rows", note: rows.length > c.rows ? "too many rows — check filters, joins and DISTINCT" : "too few rows — check filters and joins" });
    if (rows.length !== c.rows) return out;

    const pool = [...c.colHashes];
    const marks = colH.map(h => { const i = pool.indexOf(h); if (i >= 0) pool.splice(i, 1); return i >= 0; });
    const nMatch = marks.filter(Boolean).length;
    items.push({ ok: nMatch === c.cols && cols === c.cols, label: "Column totals",
      note: res.columns.map((name, j) => `${name} ${marks[j] ? "✓" : "✗"}`).join(" · ") });
    if (nMatch !== c.cols || cols !== c.cols) return out;

    const setOk = setH === c.setHash;
    items.push({ ok: setOk, label: "Rows combine", note: setOk ? "every row matches" : "right values, combined into rows differently — check GROUP BY and joins" });
    if (!setOk) return out;
    if (c.ordered) {
      const seqOk = (await fp(q.id, "seq" + canon.join(ROW))) === c.seqHash;
      items.push({ ok: seqOk, label: "Order", note: seqOk ? "sorted as asked" : "right rows, wrong order — check ORDER BY direction and tie-break" });
      if (!seqOk) return out;
    }
    out.ok = true;
    return out;
  }

  // Plain value check, used for the interpretation exams (their model answers are shown anyway).
  function checkValue(check, input) {
    const raw = String(input || "").trim();
    if (!raw) return { ok: false, msg: "Enter an answer first." };
    const v = parseNumber(raw);
    if (v === null) return { ok: false, msg: "That is not a number." };
    const ok = Math.abs(v - check.value) <= (check.tol || 0) + 1e-9;
    return { ok, msg: ok ? `Correct: ${fmtNum(check.value, 4)}.` : "Not correct yet." };
  }

  function reportHTML(r) {
    const list = r.items ? `<ul class="recon">${r.items.map(i => `<li class="${i.ok ? "ok" : "bad"}"><span class="mark">${i.ok ? "✓" : "✗"}</span><strong>${esc(i.label)}</strong> <span>${esc(i.note)}</span></li>`).join("")}</ul>` : "";
    const head = r.items ? (r.ok ? "Reconciles: your result matches the expected result." : "Does not reconcile yet.") : r.msg;
    return `<div class="feedback ${r.ok ? "ok" : "bad"}" role="status"><strong>${esc(head)}</strong>${list}
      ${r.hint ? `<div class="hint"><strong>Hint:</strong> ${esc(r.hint)}</div>` : ""}</div>`;
  }

  // ------------------------------------------------------------------ sql.js
  let sqlPromise = null;
  const dbCache = {};
  function sqlEngine() {
    if (!sqlPromise) {
      if (typeof initSqlJs !== "function") return Promise.reject(new Error("The SQL engine could not be loaded (are you offline?)."));
      sqlPromise = initSqlJs({ locateFile: f => SQLJS_CDN + f });
    }
    return sqlPromise;
  }
  function getDB(fileKey) {
    if (!dbCache[fileKey]) {
      const file = DS[fileKey].files[0];
      dbCache[fileKey] = Promise.all([sqlEngine(), fetch("files/" + file).then(r => { if (!r.ok) throw new Error("Could not download " + file); return r.arrayBuffer(); })])
        .then(([SQL, buf]) => new SQL.Database(new Uint8Array(buf)));
      dbCache[fileKey].catch(() => { delete dbCache[fileKey]; });
    }
    return dbCache[fileKey];
  }
  function runSQL(db, sql) {
    const res = db.exec(sql);
    if (!res.length) return { columns: [], values: [] };
    return res[res.length - 1];
  }
  function schemaOf(db) {
    const tables = runSQL(db, "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").values.map(r => r[0]);
    return tables.map(t => ({ t, cols: runSQL(db, `SELECT name, type FROM pragma_table_info('${t.replace(/'/g, "''")}')`).values }));
  }
  function tableHTML(res, limit = 200) {
    if (!res || !res.columns.length) return `<p class="muted small">The statement ran but returned no table.</p>`;
    const isNum = res.columns.map((_, j) => res.values.slice(0, 50).every(r => r[j] === null || typeof r[j] === "number"));
    const rows = res.values.slice(0, limit).map(r => `<tr>${r.map((v, j) => `<td class="${isNum[j] ? "num" : ""}">${v === null ? '<span class="muted">NULL</span>' : esc(v)}</td>`).join("")}</tr>`).join("");
    return `<div class="result-wrap"><table class="data"><thead><tr>${res.columns.map((c, j) => `<th class="${isNum[j] ? "num" : ""}">${esc(c)}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table></div>
      <p class="muted small">${res.values.length} row${res.values.length === 1 ? "" : "s"}${res.values.length > limit ? `, first ${limit} shown` : ""}.</p>`;
  }

  // ------------------------------------------------------------------ question component
  const METHOD_AFTER = 3;   // failed checks before the method note is offered
  function datasetFiles(key) {
    const d = DS[key];
    return d.files.map((f, i) => `<a href="files/${encodeURIComponent(f)}" download>${esc(f)} <span class="muted small">${fmtSize(d.sizes[i])}</span></a>`).join("");
  }

  // mode "practice": check immediately. mode "exam": answers are only kept; checked at Finish.
  function questionHTML(q, n, mode = "practice") {
    const st = Store.q(q.id);
    const d = DS[q.file];
    const exam = mode === "exam";
    const head = `<div class="row">
        ${n ? `<span class="eyebrow">Question ${n}</span>` : ""}${subjChip(q.subject)}
        <span class="chip">${esc(q.id)}</span><span class="chip">${esc(d.label)}</span>
        <span class="chip">≈ ${fmtNum(q.minutes, 1)} min</span>
        ${!exam && st && st.solved ? '<span class="chip ok">Solved</span>' : ""}
      </div>
      <p class="prompt">${esc(q.prompt)}</p>`;
    const examNote = exam ? `<p class="muted small">Exam mode: your answer is saved and checked when you press <strong>Finish exam</strong>.</p>` : "";
    const methodBtn = exam ? "" : `<button class="btn ghost hidden" data-act="method">Show method</button>`;
    if (q.subject === "SQL") {
      return `<section class="card question stack" data-q="${q.id}" data-mode="${mode}">${head}
        <textarea class="sql" spellcheck="false" aria-label="Your SQL query" placeholder="SELECT …">${esc(drafts[q.id] || "")}</textarea>
        <div class="row">
          <button class="btn${exam ? " primary" : ""}" data-act="run">Run</button>
          ${exam ? "" : '<button class="btn primary" data-act="check">Check answer</button>'}
          <span class="muted small"><span class="kbd">Ctrl</span> + <span class="kbd">Enter</span> runs</span>
          <span class="spacer"></span>
          <button class="btn ghost" data-act="schema">Tables</button>${methodBtn}
        </div>
        ${examNote}
        <div class="schema hidden" data-slot="schema"></div>
        <div data-slot="feedback"></div>
        <div data-slot="method"></div>
        <div data-slot="result"></div>
      </section>`;
    }
    return `<section class="card question stack" data-q="${q.id}" data-mode="${mode}">${head}
      <p class="muted small">Work in Excel on <strong>${esc(d.files.join(", "))}</strong>, then type your final value.</p>
      <div class="answer-row">
        <input type="text" inputmode="decimal" aria-label="Your answer" placeholder="Your answer" value="${esc(drafts[q.id] || "")}">
        ${exam ? "" : '<button class="btn primary" data-act="check">Check answer</button>'}${methodBtn}
      </div>
      ${examNote}
      <div data-slot="feedback"></div>
      <div data-slot="method"></div>
    </section>`;
  }

  const drafts = {};

  // Grade a saved answer (used by Finish exam). Returns a report object.
  async function gradeDraft(q) {
    const answer = (drafts[q.id] || "").trim();
    if (!answer) return { ok: false, msg: "No answer given." };
    if (q.subject !== "SQL") return checkTyped(q, answer);
    try {
      const db = await getDB(q.file);
      return reconcile(q, runSQL(db, answer));
    } catch (e) { return { ok: false, msg: "SQL error: " + e.message }; }
  }

  function bindQuestion(root, onResult) {
    const q = Q[root.dataset.q];
    const exam = root.dataset.mode === "exam";
    const fb = $('[data-slot="feedback"]', root);
    const show = html => { fb.innerHTML = html; };
    const info = msg => show(`<div class="feedback info" role="status">${esc(msg)}</div>`);
    const field = $("textarea, input", root);
    field.addEventListener("input", () => { drafts[q.id] = field.value; });

    const methodBtn = $('[data-act="method"]', root);
    const updateMethod = () => {
      const r = Store.q(q.id);
      if (methodBtn && r && (r.solved || r.fails >= METHOD_AFTER)) methodBtn.classList.remove("hidden");
    };
    if (methodBtn) {
      updateMethod();
      methodBtn.addEventListener("click", () => {
        $('[data-slot="method"]', root).innerHTML = `<div class="feedback info"><strong>Method.</strong> ${esc(q.method)}
          <div class="muted small" style="margin-top:4px">The answer itself is never shown: exam questions are reused at the exam.</div></div>`;
      });
    }
    const record = r => {
      Store.recordQ(q.id, r.ok);
      show(reportHTML(r));
      updateMethod();
      onResult && onResult(r);
    };

    if (q.subject !== "SQL") {
      const check = async () => {
        const r = await checkTyped(q, field.value);
        if (r.empty) return info(r.msg);
        record(r);
      };
      if (!exam) {
        $('[data-act="check"]', root).addEventListener("click", check);
        field.addEventListener("keydown", e => { if (e.key === "Enter") check(); });
      }
      return;
    }

    const resultSlot = $('[data-slot="result"]', root);
    const schemaSlot = $('[data-slot="schema"]', root);
    const withDB = async fn => {
      show(`<p class="loading">Loading the ${esc(DS[q.file].label)} database…</p>`);
      try { const db = await getDB(q.file); show(""); return await fn(db); }
      catch (e) { show(`<div class="feedback bad">${esc(e.message)}</div>`); }
    };
    const execute = db => {
      try { const res = runSQL(db, field.value); resultSlot.innerHTML = tableHTML(res); return res; }
      catch (e) { resultSlot.innerHTML = ""; show(`<div class="feedback bad"><strong>SQL error:</strong> ${esc(e.message)}</div>`); return null; }
    };
    const run = () => field.value.trim() ? withDB(execute) : info("Write a query first.");
    const check = () => {
      if (!field.value.trim()) return info("Write a query first.");
      withDB(async db => {
        const res = execute(db);
        if (res) record(await reconcile(q, res));
      });
    };
    $('[data-act="run"]', root).addEventListener("click", run);
    if (!exam) $('[data-act="check"]', root).addEventListener("click", check);
    field.addEventListener("keydown", e => {
      if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) { e.preventDefault(); run(); }
      if (e.key === "Tab" && !e.shiftKey) { e.preventDefault(); const s = field.selectionStart; field.setRangeText("  ", s, field.selectionEnd, "end"); }
    });
    $('[data-act="schema"]', root).addEventListener("click", () => {
      if (!schemaSlot.classList.toggle("hidden") && !schemaSlot.innerHTML)
        withDB(db => {
          schemaSlot.innerHTML = schemaOf(db).map(({ t, cols }) =>
            `<details><summary>${esc(t)}</summary><div class="cols">${cols.map(c => esc(c[0]) + (c[1] ? ` <span>${esc(c[1])}</span>` : "")).join(", ")}</div></details>`).join("");
        });
    });
  }

  // ------------------------------------------------------------------ views
  let cleanup = null;

  function viewHome() {
    const solved = B.questions.filter(q => Store.status(q.id) === "ok").length;
    const examsDone = Object.keys(Store.data.exams).length;
    app.innerHTML = `
      <section class="hero">
        <p class="eyebrow">Data Analytics in Accounting · oral exam</p>
        <h1>Practise the exact exams you can get at the oral exam.</h1>
        <p class="lead">At the exam you receive one full <strong>data manipulation</strong> exam and one full <strong>data interpretation</strong> exam.
        Every exam here is built only from the course cases and data files, and every answer is checked instantly.</p>
      </section>
      <p class="promise">The exams on this site are the exam pool. Knowing what is coming should take the guesswork out of preparing — and practising them is the best preparation there is.</p>
      <div class="format" style="margin-top:18px">
        <div class="card">
          <h2>${subjChip("Excel")}${subjChip("SQL")} Data manipulation</h2>
          <ul>
            <li>One Excel data set and one SQL database from the course cases</li>
            <li>2 Excel tasks + 3 SQL tasks, about 7–10 minutes</li>
            <li>Excel: work in the file and type the final value. SQL: write the query here — it runs in your browser</li>
            <li>Feedback works like control totals: does your result reconcile (rows, column totals, order)? Typical mistakes get a targeted hint — the answer itself is never shown</li>
          </ul>
          <div class="row"><a class="btn primary" href="#/exams">Practise exams</a><a class="btn" href="#/questions">Single questions</a></div>
        </div>
        <div class="card">
          <h2><span class="chip reg">Regression</span> Data interpretation</h2>
          <ul>
            <li>Four regression outputs, as in the restaurant case</li>
            <li>A prediction, a single-variable interpretation, a squared term and an interaction</li>
            <li>Predictions are checked; written answers are compared with a model answer and checklist</li>
          </ul>
          <div class="row"><a class="btn primary" href="#/interpretation">Practise interpretation</a><a class="btn" href="#/concepts">Concept checks</a></div>
        </div>
      </div>
      <div class="grid grid-3" style="margin-top:18px">
        <div class="card stat"><div class="v">${solved}<span class="muted" style="font-size:1rem"> / ${B.questions.length}</span></div><div class="l">manipulation questions solved</div></div>
        <div class="card stat"><div class="v">${examsDone}<span class="muted" style="font-size:1rem"> / ${B.exams.length}</span></div><div class="l">manipulation exams finished</div></div>
        <div class="card stat"><div class="v">${Object.keys(Store.data.reg).length}<span class="muted" style="font-size:1rem"> / ${B.regression.length}</span></div><div class="l">interpretation exams reviewed</div></div>
      </div>
      <h2 style="margin-top:28px">Data sets used</h2>
      <div class="grid grid-2">${Object.entries(DS).map(([k, d]) => `
        <div class="card"><div class="row"><strong>${esc(d.label)}</strong><span class="spacer"></span><span class="chip ${d.kind === "sqlite" ? "sql" : "excel"}">${d.kind === "sqlite" ? "SQL" : "Excel"}</span></div>
        <p class="muted small" style="margin:6px 0">${esc(d.course)} — ${esc(d.about)}</p><div class="files">${datasetFiles(k)}</div></div>`).join("")}
      </div>`;
  }

  function examTitle(e) { return e.files.map(f => DS[f].label.replace(/ \(.*\)$/, "")).join(" + "); }

  function viewExams(params) {
    const filter = params.get("file") || "";
    const list = B.exams.filter(e => !filter || e.files.includes(filter));
    app.innerHTML = `
      <p class="eyebrow">Data manipulation</p>
      <h1>Manipulation exams</h1>
      <p class="lead">Each exam combines one Excel data set and one SQL database: 2 Excel tasks and 3 SQL tasks. Download the files before you start the timer — opening and importing is part of the exam.</p>
      <div class="row" style="margin:14px 0"><button class="btn primary" id="pick">Choose an exam for me</button>
        <span class="muted small">Picks an exam you have not finished yet.</span></div>
      <div class="filters"><label class="field">Data set<select id="f-file"><option value="">All data sets</option>
        ${Object.entries(DS).filter(([k]) => B.exams.some(e => e.files.includes(k))).map(([k, d]) => `<option value="${k}" ${k === filter ? "selected" : ""}>${esc(d.label)}</option>`).join("")}
      </select></label><span class="muted small">${list.length} exams</span></div>
      <div class="exam-grid">${list.map(e => {
        const r = Store.data.exams[e.id];
        return `<a class="exam-card" href="#/exam/${e.id}"><div class="row"><span class="id">${e.id}</span><span class="spacer"></span>
          ${r ? `<span class="chip ${r.correct === r.total ? "ok" : "warn"}">${r.correct}/${r.total}</span>` : ""}</div>
          <h3>${esc(examTitle(e))}</h3><div class="row">${subjChip("Excel")}${subjChip("SQL")}<span class="chip">≈ ${fmtNum(e.minutes, 1)} min</span></div></a>`;
      }).join("")}</div>`;
    $("#f-file").addEventListener("change", ev => { location.hash = "#/exams" + (ev.target.value ? "?file=" + ev.target.value : ""); });
    $("#pick").addEventListener("click", () => {
      const open = list.filter(e => !Store.data.exams[e.id]);
      const pool = open.length ? open : list;
      location.hash = "#/exam/" + pool[Math.floor(Math.random() * pool.length)].id;
    });
  }

  function viewExam(id) {
    const e = EX[id];
    if (!e) return notFound();
    const qs = e.questions.map(x => Q[x]);
    const total = Math.round(e.minutes * 60);
    const t = { remaining: total, elapsed: 0, running: false, h: null };
    let current = 0;
    let finished = false;   // like the real exam: no feedback until the student hands in
    const results = {};     // this attempt's outcome per question, shown in the sidebar after Finish
    app.innerHTML = `
      <div class="row"><a href="#/exams" class="btn ghost">← All exams</a></div>
      <p class="eyebrow" style="margin-top:8px">${e.id} · Data manipulation exam · ≈ ${fmtNum(e.minutes, 1)} minutes</p>
      <h1>${esc(examTitle(e))}</h1>
      <p class="muted small">As at the exam, you get no feedback while you work. Press <strong>Finish exam</strong> to have every answer reconciled.</p>
      <div class="exam-layout" style="margin-top:14px">
        <aside class="sidebar">
          <div class="card timer">
            <div class="sub">Time remaining</div>
            <div class="clock" id="clock">${clock(total)}</div>
            <div class="sub">Elapsed <span id="elapsed">0:00</span></div>
            <div class="row" style="justify-content:center;margin-top:10px">
              <button class="btn primary" id="t-start">Start</button>
              <button class="btn" id="t-reset" title="Set both clocks back to the start">Reset</button>
            </div>
          </div>
          <div class="card"><h3>Files</h3><div class="files">${e.files.map(datasetFiles).join("")}</div>
            <p class="muted small" style="margin:8px 0 0">SQL databases also load here automatically when you run a query.</p></div>
          <div class="card"><h3>Questions</h3><div class="qnav" id="qnav"></div>
            <button class="btn primary" id="finish" style="width:100%;margin-top:10px">Finish exam</button></div>
        </aside>
        <div id="qpane"></div>
      </div>`;
    const nav = $("#qnav"), pane = $("#qpane");
    const navDot = q => finished ? (results[q.id] ? "ok" : "bad") : (drafts[q.id] || "").trim() ? "saved" : "";
    const drawNav = () => {
      nav.innerHTML = qs.map((q, i) => `<button class="${i === current ? "active" : ""}" data-i="${i}" aria-current="${i === current}">
        <span class="dot ${navDot(q)}"></span><span class="n">${String(i + 1).padStart(2, "0")}</span>${esc(q.subject)} <span class="muted small">${q.id}</span></button>`).join("");
      $$("button", nav).forEach(b => b.addEventListener("click", () => { current = +b.dataset.i; drawQ(); }));
    };
    const drawQ = () => {
      pane.innerHTML = questionHTML(qs[current], current + 1, finished ? "practice" : "exam") + `
        <div class="row" style="margin-top:12px"><button class="btn" id="prev" ${current === 0 ? "disabled" : ""}>← Previous</button><span class="spacer"></span>
        <button class="btn" id="next" ${current === qs.length - 1 ? "disabled" : ""}>Next →</button></div>`;
      const root = $(".question", pane);
      bindQuestion(root, r => { results[qs[current].id] = r.ok || results[qs[current].id]; drawNav(); });
      $("textarea, input", root).addEventListener("input", drawNav);
      $("#prev").addEventListener("click", () => { current--; drawQ(); });
      $("#next").addEventListener("click", () => { current++; drawQ(); });
      drawNav();
    };
    const tick = () => {
      t.remaining--; t.elapsed++;
      const c = $("#clock");
      c.textContent = clock(t.remaining);
      c.className = "clock" + (t.remaining < 0 ? " over" : t.remaining <= 60 ? " low" : "");
      $("#elapsed").textContent = clock(t.elapsed);
      if (t.remaining === 0) c.setAttribute("aria-label", "Time is up");
    };
    $("#t-start").addEventListener("click", ev => {
      t.running = !t.running;
      ev.target.textContent = t.running ? "Pause" : "Resume";
      if (t.running) t.h = setInterval(tick, 1000); else clearInterval(t.h);
    });
    $("#t-reset").addEventListener("click", () => {
      clearInterval(t.h); Object.assign(t, { remaining: total, elapsed: 0, running: false });
      $("#t-start").textContent = "Start"; $("#clock").textContent = clock(total); $("#clock").className = "clock"; $("#elapsed").textContent = "0:00";
    });
    $("#finish").addEventListener("click", async () => {
      const unanswered = qs.filter(q => !(drafts[q.id] || "").trim()).length;
      if (!finished && unanswered && !confirm(`${unanswered} question${unanswered > 1 ? "s have" : " has"} no answer yet. Finish anyway?`)) return;
      clearInterval(t.h); t.running = false; $("#t-start").textContent = "Resume";
      pane.innerHTML = `<section class="card"><p class="loading">Reconciling your answers…</p></section>`;
      const reports = [];
      for (const q of qs) {
        const r = await gradeDraft(q);
        if ((drafts[q.id] || "").trim()) Store.recordQ(q.id, r.ok);
        results[q.id] = r.ok;
        reports.push(r);
      }
      finished = true;
      const correct = reports.filter(r => r.ok).length;
      Store.data.exams[e.id] = { correct, total: qs.length, seconds: t.elapsed, at: Date.now() }; Store.save();
      pane.innerHTML = `<section class="card stack"><h2>Exam result: ${correct} of ${qs.length}</h2>
        <p class="muted">${t.elapsed ? `Time used ${clock(t.elapsed)} of ${clock(total)}. ` : ""}Each answer is reconciled below. Open a question to keep working on it — checking is now switched on.</p>
        ${qs.map((q, i) => `<div class="stack" style="border-top:1px solid var(--border);padding-top:12px">
          <div class="row"><span class="eyebrow">Question ${i + 1}</span>${subjChip(q.subject)}<span class="chip">${q.id}</span><span class="spacer"></span>
          <button class="btn" data-open="${i}">${reports[i].ok ? "Review" : "Work on it"}</button></div>
          <p style="margin:0">${esc(q.prompt)}</p>${reportHTML(reports[i])}</div>`).join("")}
        <p class="muted small">At the oral exam you also explain how you did it — practise saying your steps out loud.</p>
        <div class="row"><a class="btn primary" href="#/exams">Next exam</a></div></section>`;
      $$("[data-open]", pane).forEach(b => b.addEventListener("click", () => { current = +b.dataset.open; drawQ(); }));
      drawNav();
    });
    drawQ();
    cleanup = () => clearInterval(t.h);
  }

  let bankList = [];
  function viewBank(params) {
    const f = { file: params.get("file") || "", subject: params.get("subject") || "", topic: params.get("topic") || "", status: params.get("status") || "" };
    const topics = [...new Set(B.questions.flatMap(q => q.topics))].sort();
    bankList = B.questions.filter(q => (!f.file || q.file === f.file) && (!f.subject || q.subject === f.subject) && (!f.topic || q.topics.includes(f.topic))
      && (!f.status || (f.status === "open" ? Store.status(q.id) !== "ok" : Store.status(q.id) === f.status)));
    const opt = (v, label, cur) => `<option value="${esc(v)}" ${v === cur ? "selected" : ""}>${esc(label)}</option>`;
    app.innerHTML = `
      <p class="eyebrow">Data manipulation</p><h1>Question bank</h1>
      <p class="lead">All ${B.questions.length} Excel and SQL questions the exams are drawn from. Filter by data set or skill to train a weak spot.</p>
      <div class="filters">
        <label class="field">Data set<select data-f="file">${opt("", "All", f.file)}${Object.entries(DS).filter(([k]) => B.questions.some(q => q.file === k)).map(([k, d]) => opt(k, d.label, f.file)).join("")}</select></label>
        <label class="field">Subject<select data-f="subject">${opt("", "All", f.subject)}${opt("Excel", "Excel", f.subject)}${opt("SQL", "SQL", f.subject)}</select></label>
        <label class="field">Skill<select data-f="topic">${opt("", "All", f.topic)}${topics.map(t => opt(t, topicLabel(t), f.topic)).join("")}</select></label>
        <label class="field">Status<select data-f="status">${opt("", "All", f.status)}${opt("open", "Not solved", f.status)}${opt("bad", "Attempted, not solved", f.status)}${opt("ok", "Solved", f.status)}</select></label>
        <span class="muted small">${bankList.length} questions</span>
      </div>
      <div class="list">${bankList.map(q => `<a class="list-item" href="#/q/${q.id}"><span class="dot ${Store.status(q.id)}"></span>
        <div><div class="title">${esc(q.prompt)}</div><div class="meta">${subjChip(q.subject)}<span class="chip">${q.id}</span><span class="chip">${esc(DS[q.file].label)}</span>
        ${q.topics.slice(0, 3).map(t => `<span class="chip">${esc(topicLabel(t))}</span>`).join("")}</div></div>
        <span class="muted small">≈ ${fmtNum(q.minutes, 1)} min</span></a>`).join("") || '<p class="muted">No questions match these filters.</p>'}</div>`;
    $$("[data-f]").forEach(s => s.addEventListener("change", () => {
      const p = new URLSearchParams();
      $$("[data-f]").forEach(x => x.value && p.set(x.dataset.f, x.value));
      location.hash = "#/questions" + (p.toString() ? "?" + p : "");
    }));
  }

  function viewQuestion(id) {
    const q = Q[id];
    if (!q) return notFound();
    const list = bankList.length && bankList.includes(q) ? bankList : B.questions;
    const i = list.indexOf(q);
    const d = DS[q.file];
    app.innerHTML = `
      <div class="row"><a href="#/questions" class="btn ghost">← Question bank</a><span class="spacer"></span>
        ${i > 0 ? `<a class="btn" href="#/q/${list[i - 1].id}">← Previous</a>` : ""}${i < list.length - 1 ? `<a class="btn" href="#/q/${list[i + 1].id}">Next →</a>` : ""}</div>
      <div class="exam-layout" style="margin-top:14px">
        <aside class="sidebar"><div class="card"><h3>${esc(d.label)}</h3><p class="muted small">${esc(d.about)}</p><div class="files">${datasetFiles(q.file)}</div></div>
          <div class="card"><h3>Used in exams</h3><p class="small">${B.exams.filter(e => e.questions.includes(id)).map(e => `<a href="#/exam/${e.id}">${e.id}</a>`).join(", ") || '<span class="muted">Practice only</span>'}</p></div></aside>
        <div>${questionHTML(q)}</div>
      </div>`;
    bindQuestion($(".question"));
  }

  function viewInterpList() {
    app.innerHTML = `
      <p class="eyebrow">Data interpretation</p><h1>Interpretation exams</h1>
      <p class="lead">Each exam gives four regression outputs from one setting: predict, interpret a single coefficient, interpret a squared term and interpret an interaction.
      The two restaurant exams use models estimated on the course's restaurant data; the others are synthetic teaching values in accounting settings.</p>
      <div class="exam-grid" style="margin-top:16px">${B.regression.map(r => `<a class="exam-card" href="#/interp/${r.id}">
        <div class="row"><span class="id">${r.id}</span><span class="spacer"></span>${Store.data.reg[r.id] ? '<span class="chip ok">Reviewed</span>' : ""}</div>
        <h3>${esc(r.title)}</h3><div class="row"><span class="chip reg">4 questions</span>${r.real ? '<span class="chip">course data</span>' : ""}</div></a>`).join("")}</div>`;
  }

  function viewInterp(id) {
    const r = REG[id];
    if (!r) return notFound();
    const coefTable = q => `<table class="coef"><thead><tr><th>Term</th><th class="num">Estimate</th><th class="num">p-value</th></tr></thead><tbody>
      ${q.coefs.map(c => `<tr><td>${esc(c.term)}</td><td class="num">${fmtNum(c.est, 4)}</td><td class="num">${c.p < 0.001 ? "&lt; 0.001" : c.p.toFixed(3)}</td></tr>`).join("")}</tbody></table>`;
    const kindLabel = { prediction: "Prediction", continuous: "Continuous variable", dummy: "Dummy variable", quadratic: "Squared term", interaction: "Interaction" };
    app.innerHTML = `
      <div class="row"><a href="#/interpretation" class="btn ghost">← All interpretation exams</a></div>
      <p class="eyebrow" style="margin-top:8px">${r.id} · Data interpretation exam</p><h1>${esc(r.title)}</h1>
      <div class="card stack"><p>${esc(r.context)}</p>
        <table class="topics"><tbody>${Object.entries(r.variables).map(([k, v]) => `<tr><td><strong>${esc(k)}</strong></td><td>${esc(v)}</td></tr>`).join("")}</tbody></table>
        <p class="muted small">Use the 5% significance level. Interpret associations; do not claim causation.</p></div>
      ${r.questions.map((q, i) => `
        <section class="card stack" data-rq="${i}" style="margin-top:14px">
          <div class="row"><span class="eyebrow">Question ${i + 1}</span><span class="chip reg">${kindLabel[q.kind]}</span></div>
          <div class="equation">${esc(q.equation)}</div>
          ${coefTable(q)}
          <p class="prompt" style="font-weight:500">${esc(q.prompt)}</p>
          ${q.answer ? `<div class="answer-row"><input type="text" inputmode="decimal" placeholder="Your number"><button class="btn primary" data-act="check">Check</button></div><div data-slot="fb"></div>` : ""}
          <textarea rows="3" placeholder="Write (or say out loud) your interpretation before you look at the model answer…" aria-label="Your interpretation"></textarea>
          <div><button class="btn" data-act="model">Show model answer</button></div>
          <div class="hidden stack" data-slot="model">
            <div class="feedback info">${esc(q.model)}</div>
            <div class="points"><p class="small muted" style="margin:0">Tick what your answer covered:</p>${q.points.map(p => `<label><input type="checkbox"> ${esc(p)}</label>`).join("")}</div>
          </div>
        </section>`).join("")}`;
    $$("[data-rq]").forEach(sec => {
      const q = r.questions[+sec.dataset.rq];
      const chk = $('[data-act="check"]', sec);
      if (chk) {
        const inp = $("input[type=text]", sec);
        const go = () => { const res = checkValue(q.answer, inp.value); $('[data-slot="fb"]', sec).innerHTML = `<div class="feedback ${res.ok ? "ok" : res.msg.startsWith("Enter") ? "info" : "bad"}">${esc(res.msg)}</div>`; };
        chk.addEventListener("click", go);
        inp.addEventListener("keydown", e => { if (e.key === "Enter") go(); });
      }
      $('[data-act="model"]', sec).addEventListener("click", () => {
        $('[data-slot="model"]', sec).classList.remove("hidden");
        Store.data.reg[r.id] = Date.now(); Store.save();
      });
    });
  }

  function viewConcepts() {
    app.innerHTML = `<p class="eyebrow">Warm-up</p><h1>Concept checks</h1>
      <p class="lead">Short questions on the ideas behind the cases (ETL, joins, the four V's, SQL, P-card controls). Expect to be asked "why" at the oral exam.</p>
      <div class="stack" style="margin-top:14px">${B.concepts.map((c, i) => `<section class="card" data-c="${i}">
        <div class="row"><span class="chip">${esc(c.topic)}</span><span class="muted small">${esc(c.source)}</span></div>
        <p class="prompt" style="font-weight:500;margin:8px 0">${esc(c.prompt)}</p>
        <div class="grid" style="gap:6px">${c.options.map((o, j) => `<button class="btn" style="justify-content:flex-start;text-align:left" data-o="${j}">${esc(o)}</button>`).join("")}</div>
        <div data-slot="fb" style="margin-top:8px"></div></section>`).join("")}</div>`;
    $$("[data-c]").forEach(sec => {
      const c = B.concepts[+sec.dataset.c];
      $$("[data-o]", sec).forEach(b => b.addEventListener("click", () => {
        const ok = +b.dataset.o === c.correct;
        Store.data.concepts[c.id] = ok; Store.save();
        $$("[data-o]", sec).forEach(x => { x.disabled = true; if (+x.dataset.o === c.correct) x.classList.add("primary"); });
        $('[data-slot="fb"]', sec).innerHTML = `<div class="feedback ${ok ? "ok" : "bad"}"><strong>${ok ? "Correct." : "Not quite."}</strong> ${esc(c.explain)}</div>`;
      }));
    });
  }

  function viewProgress() {
    const attempted = B.questions.filter(q => Store.q(q.id));
    const solved = attempted.filter(q => Store.status(q.id) === "ok");
    const byTopic = {};
    for (const q of B.questions) for (const t of q.topics) {
      const s = byTopic[t] || (byTopic[t] = { total: 0, tried: 0, solved: 0 });
      s.total++; if (Store.q(q.id)) s.tried++; if (Store.status(q.id) === "ok") s.solved++;
    }
    const rows = Object.entries(byTopic).sort((a, b) => (a[1].tried ? a[1].solved / a[1].tried : 2) - (b[1].tried ? b[1].solved / b[1].tried : 2) || b[1].total - a[1].total);
    const pct = (a, b) => b ? Math.round(100 * a / b) : 0;
    app.innerHTML = `<p class="eyebrow">Your preparation</p><h1>Progress</h1>
      <p class="lead">Stored only in this browser. Topics with the lowest success rate are listed first — that is where practice pays off most.</p>
      <div class="grid grid-3" style="margin:16px 0">
        <div class="card stat"><div class="v">${solved.length}/${B.questions.length}</div><div class="l">questions solved</div><div class="bar"><span style="width:${pct(solved.length, B.questions.length)}%"></span></div></div>
        <div class="card stat"><div class="v">${Object.keys(Store.data.exams).length}/${B.exams.length}</div><div class="l">manipulation exams finished</div><div class="bar"><span style="width:${pct(Object.keys(Store.data.exams).length, B.exams.length)}%"></span></div></div>
        <div class="card stat"><div class="v">${Object.keys(Store.data.reg).length}/${B.regression.length}</div><div class="l">interpretation exams reviewed</div><div class="bar"><span style="width:${pct(Object.keys(Store.data.reg).length, B.regression.length)}%"></span></div></div>
      </div>
      <div class="card"><h2>By skill</h2><div style="overflow-x:auto"><table class="topics"><thead><tr><th>Skill</th><th class="num">Solved / tried</th><th class="num">Questions</th><th></th></tr></thead><tbody>
        ${rows.map(([t, s]) => `<tr><td>${esc(topicLabel(t))}</td><td class="num">${s.tried ? `${s.solved}/${s.tried}` : '<span class="muted">—</span>'}</td><td class="num">${s.total}</td>
        <td><a href="#/questions?topic=${encodeURIComponent(t)}&status=open">Practise</a></td></tr>`).join("")}</tbody></table></div></div>
      <div class="row" style="margin-top:16px"><span class="spacer"></span><button class="btn ghost" id="reset">Reset my progress</button></div>`;
    $("#reset").addEventListener("click", () => {
      if (confirm("Delete all progress stored in this browser?")) { Store.data = { q: {}, exams: {}, reg: {}, concepts: {} }; Store.save(); viewProgress(); }
    });
  }

  function notFound() { app.innerHTML = `<h1>Not found</h1><p><a href="#/">Back to the start page</a></p>`; }

  // ------------------------------------------------------------------ router
  function route() {
    if (cleanup) { cleanup(); cleanup = null; }
    const [path, qs] = location.hash.replace(/^#/, "").split("?");
    const parts = path.split("/").filter(Boolean);
    const params = new URLSearchParams(qs || "");
    const section = parts[0] || "";
    const navKey = { exams: "exams", exam: "exams", interpretation: "interpretation", interp: "interpretation", questions: "questions", q: "questions", progress: "progress" }[section];
    $$(".mainnav a").forEach(a => a.classList.toggle("active", a.dataset.nav === navKey));
    switch (section) {
      case "": viewHome(); break;
      case "exams": viewExams(params); break;
      case "exam": viewExam(parts[1]); break;
      case "questions": viewBank(params); break;
      case "q": viewQuestion(parts[1]); break;
      case "interpretation": viewInterpList(); break;
      case "interp": viewInterp(parts[1]); break;
      case "concepts": viewConcepts(); break;
      case "progress": viewProgress(); break;
      default: notFound();
    }
    window.scrollTo(0, 0);
    app.focus({ preventScroll: true });
  }
  window.addEventListener("hashchange", route);
  route();
})();
